    public static bool ContainsUrdu(string text)
    {
        foreach (var c in text)
        {
            if ((c >= 0x0600 && c <= 0x06FF) ||
                (c >= 0x0750 && c <= 0x077F) ||
                (c >= 0xFB50 && c <= 0xFDFF) ||
                (c >= 0xFE70 && c <= 0xFEFF))
            {
                return true;
            }
        }
        return false;
    }

    public static string ConvertSrt(string srtContent)
    {
        if (!ContainsUrdu(srtContent))
            return srtContent;

        var lines = srtContent.Split(["\r\n", "\r", "\n"], StringSplitOptions.None);
        var sb = new StringBuilder();

        for (var i = 0; i < lines.Length; i++)
        {
            var line = lines[i];

            // Preserve blank lines, numeric segment indexes, and timestamp ranges
            if (string.IsNullOrWhiteSpace(line) ||
                int.TryParse(line.Trim(), out _) ||
                line.Contains("-->"))
            {
                sb.AppendLine(line);
            }
            else
            {
                sb.AppendLine(ConvertText(line));
            }
        }

        return sb.ToString().TrimEnd() + Environment.NewLine;
    }

    public static string ConvertText(string text)
    {
        if (!ContainsUrdu(text))
            return text;

        var sb = new StringBuilder();
        var word = new StringBuilder();

        for (var i = 0; i < text.Length; i++)
        {
            var c = text[i];
            if (char.IsWhiteSpace(c) || c is '۔' or '،' or '؟' or '.' or ',' or '?' or '!' or ':' or ';' or '(' or ')' or '[' or ']')
            {
                if (word.Length > 0)
                {
                    sb.Append(ConvertWord(word.ToString()));
                    word.Clear();
                }

                // Map Urdu punctuation to Devanagari / Latin punctuation
                sb.Append(c switch
                {
                    '۔' => "।",
                    '،' => ",",
                    '؟' => "?",
                    _ => c.ToString()
                });
            }
            else
            {
                word.Append(c);
            }
        }

        if (word.Length > 0)
        {
            sb.Append(ConvertWord(word.ToString()));
        }

        return sb.ToString();
    }

    private static string ConvertWord(string word)
    {
        word = word.Replace('\u0B9A', 'س');
        if (!ContainsUrdu(word))
            return word;

        if (CommonWords.TryGetValue(word, out var mapped))
            return mapped;

        var sb = new StringBuilder();
        var i = 0;
        while (i < word.Length)
        {
            if (i + 1 < word.Length && Compounds.TryGetValue(word.Substring(i, 2), out var comp))
            {
                sb.Append(comp);
                i += 2;
                continue;
            }

            var ch = word[i];
            if (i == 0 && ch == 'ا')
            {
                sb.Append('अ');
                i++;
                continue;
            }
            if (i == 0 && ch == 'ی')
            {
                sb.Append('य');
                i++;
                continue;
            }
            if (i == 0 && ch == 'و')
            {
                sb.Append('व');
                i++;
                continue;
            }

            if (SingleChars.TryGetValue(ch, out var dev))
            {
                sb.Append(dev);
            }
            else
            {
                sb.Append(ch);
            }
            i++;
        }

        return sb.ToString();
    }
